pub fn onPull(self: *ByteBlobLoader, buffer: []u8, array: JSValue) streams.Result {
            _ = array.ensureStillAlive();
            defer {
            _ = array.ensureStillAlive();
            }
            self.pulled = true;
            const store = ((self.store) orelse { return .{ .done = .{} }; });
            if (self.done) {
                return .{ .done = .{} };
            }
            var temporary = store.sharedView();
            _ = &temporary;
            temporary = temporary[@min(self.offset, temporary.len)..];
            temporary = temporary[0..@min(buffer.len, @min(temporary.len, self.remain))];
            if ((temporary.len == 0)) {
                _ = self.clearData();
                self.done = true;
                return .{ .done = .{} };
            }
            const copied = @as(Blob.SizeType, @intCast(temporary.len));
            self.remain = (self.remain - copied);
            self.offset = (self.offset + copied);
            _ = assert((buffer.ptr != temporary.ptr));
            _ = @memcpy(buffer[0..temporary.len], temporary);
            if ((self.remain == 0)) {
                return .{ .into_array_and_done = .{ .value = array, .len = copied } };
            }
            return .{ .into_array = .{ .value = array, .len = copied } };
    }

pub fn toAnyBlob(self: *ByteBlobLoader, globalThis: *JSGlobalObject) ?Blob.Any {
            if (self.store) |store| {
                _ = &store;
                _ = self.detachStore();
                if ((((self.offset == 0) and (self.remain == store.size())) and (self.content_type.len == 0))) {
                    if (store.toAnyBlob()) |blob| {
                        _ = &blob;
                        defer {
                        _ = store.deref();
                        }
                        return blob;
                    }
                }
                var blob = Blob.initWithStore(store, globalThis);
                _ = &blob;
                blob.offset = self.offset;
                blob.size = self.remain;
                if ((self.content_type.len > 0)) {
                    blob.content_type = self.content_type;
                    blob.content_type_was_set = (self.content_type.len > 0);
                    blob.content_type_allocated = self.content_type_allocated;
                    self.content_type = "";
                    self.content_type_allocated = false;
                }
                self.parent().is_closed = true;
                return .{ .Blob = blob };
            }
            return null;
    }

pub fn detachStore(self: *ByteBlobLoader) ?*Blob.Store {
            if (self.store) |store| {
                _ = &store;
                self.store = null;
                self.done = true;
                return store;
            }
            return null;
    }

pub fn onCancel(self: *ByteBlobLoader) void {
            _ = self.clearData();
    }

pub fn deinit(self: *ByteBlobLoader) void {
            _ = self.clearData();
            _ = self.parent().deinit();
    }

pub fn clearData(self: *ByteBlobLoader) void {
            if (self.content_type_allocated) {
                _ = default_allocator.free(self.content_type);
                self.content_type = "";
                self.content_type_allocated = false;
            }
            if (self.store) |store| {
                _ = &store;
                self.store = null;
                _ = store.deref();
            }
    }

pub fn drain(self: *ByteBlobLoader) ByteList {
            const store = ((self.store) orelse { return .{}; });
            var temporary = store.sharedView();
            _ = &temporary;
            temporary = temporary[self.offset..];
            temporary = temporary[0..@min(16384, @min(temporary.len, self.remain))];
            var byte_list = ByteList.fromBorrowedSliceDangerous(temporary);
            _ = &byte_list;
            const cloned = handleOom(byte_list.clone(default_allocator));
            self.offset = (self.offset + (if (comptime @typeInfo(Blob.SizeType) == .@"enum") @as(Blob.SizeType, @enumFromInt(cloned.len)) else @as(Blob.SizeType, cloned.len)));
            self.remain = (self.remain - (if (comptime @typeInfo(Blob.SizeType) == .@"enum") @as(Blob.SizeType, @enumFromInt(cloned.len)) else @as(Blob.SizeType, cloned.len)));
            return cloned;
    }

pub fn toBufferedValue(self: *ByteBlobLoader, globalThis: *JSGlobalObject, action: streams.BufferAction.Tag) JSError!JSValue {
            if (self.toAnyBlob(globalThis)) |blob_| {
                _ = &blob_;
                var blob = blob_;
                _ = &blob;
                return blob.toPromise(globalThis, action);
            }
            return globalThis.ERR(.BODY_ALREADY_USED, "Body already used", .{}).reject();
    }

pub fn memoryCost(self: *const ByteBlobLoader) usize {
            if (self.store) |store| {
                _ = &store;
                return store.memoryCost();
            }
            return 0;
    }
    pub const tag = webcore.ReadableStream.Tag.Blob;
    pub const Source = webcore.ReadableStream.NewSource(ByteBlobLoader, "Blob", onStart, onPull, onCancel, deinit, null, drain, memoryCost, toBufferedValue);
};

const JSGlobalObject = jsc.JSGlobalObject;
const JSValue = jsc.JSValue;
const Blob = webcore.Blob;
const streams = webcore.streams;
